if(!exists('simulation_convergence',mode='function'))library(creditratingsystem)
d<-list(model_id='frozen',model_version='1',parameter_version='1',data_fingerprint='synthetic-oracle',population_id='oracle',split_id='external',prediction_origin='EXTERNAL',evaluation_cutoff='2024-01-01',target=list(event='default',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing'))
# Published JSON SHA256 prefix digests are independently computed Python fixtures.
innovations<-list(r1=list(path_ids=as.list(paste0('p',0:3)),values=list(list(-1),list(1),list(-2),list(2))))
hashes<-c('2'='19608d4648e7174729432c6e896a621fea05cf54f13bc7378be237ca925a6ecf','4'='a057379a5a99580b660f05b86eb185eacd0107b8be17db7f4cc0de36db7a2467');runs<-list();for(dt in c(1,.5))for(N in c(2,4))runs[[length(runs)+1]]<-list(replicate_id='r1',time_step=dt,sample_size=N,path_ids=innovations$r1$path_ids[seq_len(N)],values=as.list(c(1,3,1,3)[seq_len(N)]+dt),innovation_fingerprint=unname(hashes[as.character(N)]))
contract<-list(sampling_unit='iid_paths_with_independent_replicates',metric='mean',reference='independent-path exercise',finest_time_step=.5,time_unit='years',analytic_reference=list(value=2,source='known mean'));precision<-list(confidence_level=.95,mc_half_width=.01,grid_difference_tolerance=.1)
r<-simulation_convergence(runs,innovations,sampling_contract=contract,precision=precision,design=d)$value
stopifnot(identical(vapply(r$metrics$sampling,function(s)s$estimate,numeric(1)),c(2.5,2.5,3,3)),abs(r$metrics$sampling[[2]]$mc_standard_error-1/sqrt(3))<1e-14,all(vapply(r$metrics$paired_grid_differences,function(s)s$estimate==.5&&s$mc_standard_error==0&&!s$observed_grid_tolerance_met,logical(1))))
zero<-lapply(runs,function(r){r$values<-as.list(rep(0,r$sample_size));r});contract$metric<-'bernoulli_probability';contract$analytic_reference$value<-0;r<-simulation_convergence(zero,innovations,sampling_contract=contract,precision=precision,design=d)$value;stopifnot(all(vapply(r$metrics$sampling,function(s)s$upper>0&&!s$mc_precision_met,logical(1))))
ctx<-build_calculation_context('2024-01-01','2024-01-01',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing')$value
c<-list(unit='probability',target=d$target,row_ids=list('r'),as_of='2024-01-01',known_at='2024-01-01');data<-list(a=list(value=list(.5),contract=c),b=list(value=list(.5),contract=c));nodes<-lapply(c('a','b'),function(s)list(node_id=s,operation='input',inputs=structure(list(),names=character()),parameters=list(input_id=s),output_contract=c));nodes[[3]]<-list(node_id='pool',operation='combine_pd_signals',inputs=list(a='a',b='b'),parameters=list(signal_order=list('a','b'),weights=list(.25,.75),combination_scale='linear',combination_contract=list(interpretation='estimator_pool',reference='fixed linear combination')),output_contract=c);graph<-list(graph_id='linear-oracle',graph_version='1',nodes=nodes,output_node='pool');model<-list(kind='model_graph',model_graph=graph,input_data=data,parameter_snapshots=structure(list(),names=character()),execution_context=ctx,output_row=0);specs<-lapply(c('a','b'),function(s)list(name=s,location='input',path=list(s,'value',0),lower=0,upper=1,step=.01))
r<-sensitivity_analysis(model,c(.5,.5),specs,method='finite_difference',shared_samples=NULL,design=d)$value;stopifnot(max(abs(vapply(r$metrics$local_derivatives,function(s)s$derivative,numeric(1))-c(.25,.75)))<1e-12)
levels<-expand.grid(a=c(.2,.8),b=c(.2,.8));pairs<-expand.grid(a=1:4,b=1:4);samples<-list(A=lapply(seq_len(nrow(pairs)),function(i)as.list(as.numeric(levels[pairs$a[i],]))),B=lapply(seq_len(nrow(pairs)),function(i)as.list(as.numeric(levels[pairs$b[i],]))),distribution_contract=list(independent_inputs=TRUE,reference='Cartesian exact integration oracle'))
r<-sensitivity_analysis(model,c(.5,.5),specs,method='variance_based',shared_samples=samples,design=d)$value;stopifnot(abs(r$metrics$first_order$a-.1)<1e-12,abs(r$metrics$first_order$b-.9)<1e-12,abs(r$metrics$total_order$a-.1)<1e-12,abs(r$metrics$pairwise_interactions[[1]]$second_order)<1e-12)
model$input_data$a$value<-list(.2);model$input_data$b$value<-list(.8);spec<-list(list(name='weight_a',location='parameter',path=list('nodes',2,'parameters','weights',0),lower=.1,upper=.9,step=.0001));r<-sensitivity_analysis(model,.25,spec,method='finite_difference',shared_samples=NULL,design=d)$value;stopifnot(abs(r$metrics$local_derivatives[[1]]$derivative+.45)<2e-9)
fit<-fit_binary_glm(matrix(c(0,0,1,1),ncol=1),c(0,1,0,1),link='logit',feature_order='group',fit_intercept=TRUE,target=d$target,training=list(data_fingerprint='group-counts',split_id='train',known_at='2023-01-01',data_origin='SYNTHETIC'),model_id='glm',model_version='1',weights=c(8,2,4,6));spec<-list(list(name='group',location='feature',lower=0,upper=1,step=.001));r<-sensitivity_analysis(list(kind='pd_model',fitted_model=fit),.5,spec,method='finite_difference',shared_samples=NULL,design=d)$value;p<-plogis((qlogis(.2)+qlogis(.6))/2);slope<-(qlogis(.6)-qlogis(.2))*p*(1-p);stopifnot(abs(r$metrics$baseline_value-p)<1e-8,abs(r$metrics$local_derivatives[[1]]$derivative-slope)<3e-8)
